#include <stdio.h>
#include <string.h>

#define MAX_LEN 1024  // 0x400 characters, plus terminating NUL makes 0x401 total

int main(int argc, char *argv[]) {
    // 1. Argument count handling
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    // 2. Length checks (each string must be shorter than 0x401 bytes)
    if (strlen(argv[1]) >= MAX_LEN + 1 || strlen(argv[2]) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }

    // 3. Build frequency table for first string, ignoring spaces and case
    int freq[256] = {0};
    for (const char *p = argv[1]; *p != '\0'; ++p) {
        if (*p == ' ') continue;               // ignore spaces
        unsigned char c = (unsigned char)*p;
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A'); // case‑insensitive
        ++freq[c];
    }

    // 4. Subtract frequencies for second string, same rules
    for (const char *p = argv[2]; *p != '\0'; ++p) {
        if (*p == ' ') continue;
        unsigned char c = (unsigned char)*p;
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A');
        --freq[c];
    }

    // 5. Determine if all counters are zero
    int is_anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (freq[i] != 0) {
            is_anagram = 0;
            break;
        }
    }

    puts(is_anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
